fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Precondition: start + sub.len() <= main.len()
    if start + sub.len() > main.len() {
        return false;
    }

    for i in 0..sub.len() {
        if main[start + i] != sub[i] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    let n = main.len();
    let m = sub.len();

    // The empty subarray always qualifies.
    if m == 0 {
        return true;
    }

    // If sub is longer than main, it can't be contained.
    if m > n {
        return false;
    }

    // Try every possible starting position.
    // We go up to n - m inclusive so that start + m <= n.
    for start in 0..=(n - m) {
        if check_match_at(main, sub, start) {
            return true;
        }
    }

    false
}